// ── Canvas-based helper ──
window.drawQRToCanvas = function(text, canvas, size){
  size = size || 220;
  canvas.width  = size;
  canvas.height = size;
  const qr = new b(4, {bit:2});    // level H
  qr.addData(text); qr.make();
  const ctx = canvas.getContext('2d');
  const n   = qr.getModuleCount();
  const cell= size / n;
  ctx.fillStyle = '#ffffff'; ctx.fillRect(0,0,size,size);
  ctx.fillStyle = '#000000';
  for(let r=0;r<n;r++) for(let c=0;c<n;c++){
    if(qr.isDark(r,c)){
      ctx.fillRect(Math.round(c*cell), Math.round(r*cell),
                   Math.ceil(cell),    Math.ceil(cell));
    }
  }
};
